			var exprResult Node = IR_exprResult(IR_assign(NodeUtil_newQName_AbstractCompiler_String(this.compiler_, (sstr_(qualifiedPath)+sstr_(fnName))), fnValue))
			exprResult.srcrefTreeIfMissing(behaviorFunction.name_)
